<?phpif ( ! current_user_can( 'manage_options' ) ) {	return;}$message = '';$setting_website_general = get_option( '_shw_settings_set_general', [] );$setting_website_smtp = get_option('_shw_settings_set_smtp',[]);$set_index_website = get_option('_shw_set_index_website',[]);if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['submit'])) {if (!isset($_POST['_nonce_tns_setting_general']) || !wp_verify_nonce($_POST['_nonce_tns_setting_general'], '_nonce_tns_setting_general')) {	$message = '<div class="notice notice-error is-dismissible"><p>اعتبارسنجی امنیتی انجام نشد!</p></div>';} else {    $select_index_data =  intval($_POST['_tnm_show_index'] ?? 1);	$setting_website_general_data  = [         'wishlist_enable'=>sanitize_text_field($_POST['wishlist_enable'] ?? 'no'),         'newsletter_enable'=>sanitize_text_field($_POST['newsletter_enable'] ?? 'no'),         'sale_plugin_or_themes_enable'=>sanitize_text_field($_POST['sale_plugin_or_themes_enable'] ?? 'no'),        'register_from_enable'=>sanitize_text_field($_POST['register_from_enable'] ?? 'no'),        'register_from_sms_enable'=>sanitize_text_field($_POST['register_from_sms_enable'] ?? 'no'),        'adv_enable'=>sanitize_text_field($_POST['adv_enable'] ?? 'no'),         'exclude_category_id'=>sanitize_text_field($_POST['exclude_category'] ?? ' '),         'link_enamad' => sanitize_text_field($_POST['input-enamad'] ?? ' '),         'link_zarinpal' => sanitize_text_field($_POST['input-zarinpal'] ?? ' ')    ];	$setting_website_smtp_data = [		'host'     =>sanitize_text_field($_POST['host-fs'] ?? ' '),		'port'     =>sanitize_text_field($_POST['port-fs'] ?? ' '),	    'username' =>sanitize_text_field($_POST['username-fs'] ?? ' '),        'password' =>sanitize_text_field($_POST['password-fs'] ?? ' '),        'from'     =>sanitize_text_field($_POST['from-fs'] ?? ' '),        'FormName' =>sanitize_text_field($_POST['FormName-fs'] ?? ' ')    ];	update_option('_shw_settings_set_general', $setting_website_general_data);    update_option('_shw_settings_set_smtp',$setting_website_smtp_data);    update_option('_shw_set_index_website', $select_index_data);	$setting_website_general = $setting_website_general_data;    $setting_website_smtp = $setting_website_smtp_data ;    $set_index_website = $select_index_data;	$message = '<div class="notice notice-success is-dismissible"><p>تنظیمات با موفقیت ذخیره شد!</p></div>';}}?><div class="uk-container">    <?php echo $message; ?>    <div class="uk-flex-inline uk-flex-stretch uk-margin-top">        <h4 class="uk-margin-left uk-text-right">            <span class="uk-text-primary"><?php echo esc_html( get_admin_page_title() ); ?></span>            <span uk-icon="info"                  uk-tooltip="title: ابتدا صفحه ای اصلی وب سایت خود را انتخاب کنید!; pos: left;">           </span>        </h4>    </div>    <form method="post" class="uk-grid-small" uk-grid>        <!-- انتخاب ایندکس -->        <div class="uk-width-1-1">            <div class="uk-margin uk-grid-small uk-child-width-auto" uk-grid>                <label>                    <input type="radio" name="_tnm_show_index" value="1" <?php checked($set_index_website, 1); ?>>                    فعال کردن<!--                    <img class="tnm-radio-img" src="--><?php //echo SHW_URL. '/assets/css/admin/image/index-10.png' ?><!--" alt="index-10">-->                </label>                <label>                    <input type="radio" name="_tnm_show_index" value="2" <?php checked($set_index_website, 2); ?>>                    در حالت بروز رسانی<!--                    <img class="tnm-radio-img" src="--><?php //echo SHW_URL . '/assets/css/admin/image/index-6.png' ?><!--" alt="index-6">-->                </label>            </div>        </div>        <div class="uk-width-1-1">            <hr class="uk-divider-icon">        </div>        <!-- چک‌باکس‌ها -->        <div class="uk-width-1-1">            <div class="uk-margin"