ip="title:با زدن تیک سیستم ثبت نام در وب سایت فعال میشود!; pos: left;">                </span>            </div>            <?php if ($setting_website_general['register_from_enable'] === 'yes') : ?>            <div class="uk-margin">                <label>                    <input class="uk-checkbox" type="checkbox" name="register_from_sms_enable" value="yes" <?php checked( $setting_website_general['register_from_sms_enable'] ?? 'no', 'yes' ); ?>>                    فعال کردن سیستم SMS                </label>                <span uk-icon="info"                      uk-tooltip="title:با زدن تیک  در سیستم اس ام اس ثبت نام وب سایت فعال میشود!; pos: left;">                </span>            </div>            <?php endif; ?>            <div class="uk-margin">                <label>                    <input class="uk-checkbox" type="checkbox" name="adv_enable" value="yes" <?php checked( $setting_website_general['adv_enable'] ?? 'no', 'yes' ); ?>>                    فعال کردن سیستم تبلیغات                </label>                <span uk-icon="info"                      uk-tooltip="title:با زدن تیک  در سیستم تبلیغات در صفحه اصلی سایت فعال میشود!; pos: left;">                </span>            </div>        </div>        <!-- دسته‌بندی -->        <div class="uk-width-1-1">            <div class="uk-grid uk-child-width-1-4@s uk-grid-small uk-margin">                <div>                    <label>                        <div class="uk-margin-bottom">                            <span class="uk-badge">غیرفعال کردن دسته‌بندی</span>                            <span uk-icon="info"                                  uk-tooltip="title: آی‌دی دسته‌بندی را در اینجا قرار دهید.; pos: left;">                            </span>                        </div>                        <input class="uk-input" type="text" name="exclude_category"                               value="<?php echo esc_attr($setting_website_general['exclude_category_id'] ?? ''); ?>